1	/**
2	 * `networkx.Graph`: an undirected simple graph.
3	 *
4	 * Adjacency is kept the way NetworkX keeps it -- a mapping of node to a mapping
5	 * of neighbour to edge attributes -- with an extra table from canonical key back
6	 * to the node value the caller supplied, since the key is a string.
7	 */
8	
9	import { NetworkXError } from '../exceptions.mjs';
10	import { nodeKey } from '../utils/hashing.mjs';
11	
12	export class Graph {
13	  constructor() {
14	    /** @type {Map<string, object>} node key to node attributes */
15	    this._node = new Map();
16	    /** @type {Map<string, unknown>} node key to the value it was added as */
17	    this._nodeValue = new Map();
18	    /** @type {Map<string, Map<string, object>>} node key to neighbour keys */
19	    this._adj = new Map();
20	  }
21	
22	  is_directed() {
23	    return false;
24	  }
25	
26	  is_multigraph() {
27	    return false;
28	  }
29	
30	  /** The canonical key for a node value; see `utils/hashing.mjs`. */
31	  key(value) {
32	    return nodeKey(value);
33	  }
34	
35	  add_node(value, attributes = {}) {
36	    const key = this.key(value);
37	    if (!this._node.has(key)) {
38	      this._node.set(key, { ...attributes });
39	      this._nodeValue.set(key, value);
40	      this._adj.set(key, new Map());
41	      return;
42	    }
43	    Object.assign(this._node.get(key), attributes);
44	  }
45	
46	  add_nodes_from(values) {
47	    for (const value of values) this.add_node(value);
48	  }
49	
50	  has_node(value) {
51	    return this._node.has(this.key(value));
52	  }
53	
54	  add_edge(source, target, attributes = {}) {
55	    this.add_node(source);
56	    this.add_node(target);
57	    const sourceKey = this.key(source);
58	    const targetKey = this.key(target);
59	
60	    const existing = this._adj.get(sourceKey).get(targetKey) ?? {};
61	    Object.assign(existing, attributes);
62	    this._adj.get(sourceKey).set(targetKey, existing);
63	    this._adj.get(targetKey).set(sourceKey, existing);
64	  }
65	
66	  /**
67	   * @param {Iterable<[unknown, unknown] | [unknown, unknown, object]>} edges
68	   */
69	  add_edges_from(edges) {
70	    for (const edge of edges) {
71	      if (edge.length === 2) {
72	        this.add_edge(edge[0], edge[1]);
73	      } else if (edge.length === 3) {
74	        this.add_edge(edge[0], edge[1], edge[2]);
75	      } else {
76	        throw new NetworkXError(`Edge tuple ${JSON.stringify(edge)} must be a 2-tuple or 3-tuple.`);
77	      }
78	    }
79	  }
80	
81	  has_edge(source, target) {
82	    const neighbours = this._adj.get(this.key(source));
83	    return neighbours !== undefined && neighbours.has(this.key(target));
84	  }
85	
86	  /** Node values, in insertion order. */
87	  nodes() {
88	    return [...this._nodeValue.values()];
89	  }
90	
91	  number_of_nodes() {
92	    return this._node.size;
93	  }
94	
95	  /** `[source, target]` pairs, each undirected edge reported once. */
96	  edges() {
97	    const seen = new Set();
98	    const result = [];
99	    for (const [sourceKey, neighbours] of this._adj) {
100	      for (const targetKey of neighbours.keys()) {
101	        const canonical = sourceKey <= targetKey ? `${sourceKey}�${targetKey}` : `${targetKey}�${sourceKey}`;
102	        if (seen.has(canonical)) continue;
103	        seen.add(canonical);
104	        result.push([this._nodeValue.get(sourceKey), this._nodeValue.get(targetKey)]);
105	      }
106	    }
107	    return result;
108	  }
109	
110	  number_of_edges() {
111	    return this.edges().length;
112	  }
113	
114	  _adjacencyOf(value) {
115	    const neighbours = this._adj.get(this.key(value));
116	    if (neighbours === undefined) {
117	      throw new NetworkXError(`The node ${String(value)} is not in the graph.`);
118	    }
119	    return neighbours;
120	  }
121	
122	  /** Neighbour values of a node. */
123	  neighbors(value) {
124	    return [...this._adjacencyOf(value).keys()].map((key) => this._nodeValue.get(key));
125	  }
126	
127	  degree(value) {
128	    const neighbours = this._adjacencyOf(value);
129	    // A self-loop contributes two to an undirected degree.
130	    return neighbours.size + (neighbours.has(this.key(value)) ? 1 : 0);
131	  }
