1	/**
2	 * `networkx.DiGraph`: a directed simple graph.
3	 *
4	 * Successors and predecessors are stored separately so that in- and out-degrees
5	 * are both O(1), which is what Kahn's algorithm in `algorithms/dag.mjs` wants.
6	 */
7	
8	import { Graph } from './graph.mjs';
9	
10	export class DiGraph extends Graph {
11	  constructor() {
12	    super();
13	    /** Successors; aliased as `_adj` so inherited lookups follow edge direction. */
14	    this._succ = this._adj;
15	    /** @type {Map<string, Map<string, object>>} */
16	    this._pred = new Map();
17	  }
18	
19	  is_directed() {
20	    return true;
21	  }
22	
23	  add_node(value, attributes = {}) {
24	    const key = this.key(value);
25	    const isNew = !this._node.has(key);
26	    super.add_node(value, attributes);
27	    if (isNew) this._pred.set(key, new Map());
28	  }
29	
30	  add_edge(source, target, attributes = {}) {
31	    this.add_node(source);
32	    this.add_node(target);
33	    const sourceKey = this.key(source);
34	    const targetKey = this.key(target);
35	
36	    const existing = this._succ.get(sourceKey).get(targetKey) ?? {};
37	    Object.assign(existing, attributes);
38	    this._succ.get(sourceKey).set(targetKey, existing);
39	    this._pred.get(targetKey).set(sourceKey, existing);
40	  }
41	
42	  has_edge(source, target) {
43	    const successors = this._succ.get(this.key(source));
44	    return successors !== undefined && successors.has(this.key(target));
45	  }
46	
47	  /** Directed edges as `[source, target]` pairs, in insertion order. */
48	  edges() {
49	    const result = [];
50	    for (const [sourceKey, successors] of this._succ) {
51	      for (const targetKey of successors.keys()) {
52	        result.push([this._nodeValue.get(sourceKey), this._nodeValue.get(targetKey)]);
53	      }
54	    }
55	    return result;
56	  }
57	
58	  successors(value) {
59	    return this.neighbors(value);
60	  }
61	
62	  predecessors(value) {
63	    return [...this._predecessorsOf(value).keys()].map((key) => this._nodeValue.get(key));
64	  }
65	
66	  _predecessorsOf(value) {
67	    const predecessors = this._pred.get(this.key(value));
68	    if (predecessors === undefined) {
69	      throw new Error(`The node ${String(value)} is not in the digraph.`);
70	    }
71	    return predecessors;
72	  }
73	
74	  /** `[node, in-degree]` pairs for every node, in insertion order. */
75	  in_degree() {
76	    return [...this._nodeValue.entries()].map(([key, value]) => [value, this._pred.get(key).size]);
77	  }
78	
79	  /** `[node, out-degree]` pairs for every node, in insertion order. */
80	  out_degree() {
81	    return [...this._nodeValue.entries()].map(([key, value]) => [value, this._succ.get(key).size]);
82	  }
83	
84	  degree(value) {
85	    return this._adjacencyOf(value).size + this._predecessorsOf(value).size;
86	  }
87	}
