1	/**
2	 * Directed acyclic graph algorithms.
3	 *
4	 * The acyclicity test is the one NetworkX uses: attempt a topological ordering
5	 * with Kahn's algorithm and see whether every node comes out. Anything left over
6	 * still has an unsatisfied predecessor, which can only happen inside a cycle --
7	 * and a self-loop counts, since a node is then its own unsatisfied predecessor.
8	 */
9	
10	import { NetworkXError, NetworkXUnfeasible } from '../exceptions.mjs';
11	
12	/**
13	 * Nodes grouped into layers: every node in a generation depends only on nodes in
14	 * earlier ones.
15	 *
16	 * @param {import('../classes/digraph.mjs').DiGraph} G
17	 * @yields {unknown[]} one generation of node values
18	 */
19	export function* topological_generations(G) {
20	  if (!G.is_directed()) {
21	    throw new NetworkXError('Topological sort not defined on undirected graphs.');
22	  }
23	
24	  const remainingInDegree = new Map();
25	  let zeroInDegree = [];
26	  for (const [node, degree] of G.in_degree()) {
27	    if (degree > 0) remainingInDegree.set(G.key(node), degree);
28	    else zeroInDegree.push(node);
29	  }
30	
31	  while (zeroInDegree.length > 0) {
32	    const generation = zeroInDegree;
33	    zeroInDegree = [];
34	    for (const node of generation) {
35	      for (const child of G.neighbors(node)) {
36	        const childKey = G.key(child);
37	        const remaining = remainingInDegree.get(childKey) - 1;
38	        remainingInDegree.set(childKey, remaining);
39	        if (remaining === 0) {
40	          zeroInDegree.push(child);
41	          remainingInDegree.delete(childKey);
42	        }
43	      }
44	    }
45	    yield generation;
46	  }
47	
48	  if (remainingInDegree.size > 0) {
49	    throw new NetworkXUnfeasible(
50	      'Graph contains a cycle or graph changed during iteration',
51	    );
52	  }
53	}
54	
55	/**
56	 * A topological ordering of the nodes.
57	 *
58	 * @param {import('../classes/digraph.mjs').DiGraph} G
59	 * @yields {unknown} node values, dependencies first
60	 */
61	export function* topological_sort(G) {
62	  for (const generation of topological_generations(G)) {
63	    yield* generation;
64	  }
65	}
66	
67	/**
68	 * Whether `G` is a directed acyclic graph. Undirected graphs are never one, and
69	 * a graph with no nodes vacuously is.
70	 *
71	 * @param {import('../classes/graph.mjs').Graph} G
72	 * @returns {boolean}
73	 */
74	export function is_directed_acyclic_graph(G) {
75	  if (!G.is_directed()) return false;
76	  try {
77	    // eslint-disable-next-line no-unused-vars
78	    for (const node of topological_sort(G)) {
79	      // Drained purely for its side effect of completing the ordering.
80	    }
81	    return true;
82	  } catch (error) {
83	    if (error instanceof NetworkXUnfeasible) return false;
84	    throw error;
85	  }
86	}
