1	/**
2	 * Node identity.
3	 *
4	 * Python graphs key their nodes by hash and equality, so `1`, `1.0` and `True`
5	 * are one and the same node while arbitrarily large integers stay distinct.
6	 * JavaScript has no single value type with those properties, so every node is
7	 * reduced to a canonical string: numeric values collapse across the Number and
8	 * BigInt divide, and everything else is tagged by type so that, say, the string
9	 * '1' can never be mistaken for the integer 1.
10	 */
11	
12	/**
13	 * @param {unknown} value
14	 * @returns {string} a key equal for exactly those values Python considers the
15	 *   same dictionary key
16	 */
17	export function nodeKey(value) {
18	  switch (typeof value) {
19	    case 'bigint':
20	      return `i${value.toString()}`;
21	    case 'boolean':
22	      return value ? 'i1' : 'i0';
23	    case 'number':
24	      if (Number.isNaN(value)) return 'f:nan';
25	      if (!Number.isFinite(value)) return value > 0 ? 'f:inf' : 'f:-inf';
26	      // An integral double is the same node as the corresponding integer, which
27	      // is what makes G.add_edge(1, 2) and G.add_edge(1.0, 2) coincide.
28	      if (Number.isInteger(value)) return `i${BigInt(value).toString()}`;
29	      return `f${value}`;
30	    case 'string':
31	      return `s${value}`;
32	    case 'undefined':
33	      return 'None';
34	    case 'object': {
35	      if (value === null) return 'None';
36	      if (Array.isArray(value)) {
37	        // Length-prefixed so that nested keys cannot run together.
38	        const parts = value.map((item) => {
39	          const encoded = nodeKey(item);
40	          return `${encoded.length}:${encoded}`;
41	        });
42	        return `t${value.length}[${parts.join('')}]`;
43	      }
44	      return `o${objectIdentity(value)}`;
45	    }
46	    default:
47	      return `o${objectIdentity(value)}`;
48	  }
49	}
50	
51	let nextIdentity = 1;
52	const identities = new WeakMap();
53	
54	/** Objects without value semantics fall back to identity, as in CPython. */
55	function objectIdentity(value) {
56	  let identity = identities.get(value);
57	  if (identity === undefined) {
58	    identity = nextIdentity;
59	    nextIdentity += 1;
60	    identities.set(value, identity);
61	  }
62	  return identity;
63	}
