1	/**
2	 * `int(str)` with base 10, following CPython's two-step conversion.
3	 *
4	 * Results are returned as BigInt because Python integers are unbounded: the
5	 * graph in this port uses the parsed values as node identities, so collapsing
6	 * them onto IEEE-754 doubles would merge distinct nodes such as
7	 * 99999999999999999999998 and 99999999999999999999999.
8	 */
9	
10	import { decimalValue, isAsciiSpace, isNonAsciiSpace } from './unicode.mjs';
11	import { PyValueError } from './errors.mjs';
12	
13	/**
14	 * `_PyUnicode_TransformDecimalAndSpaceToASCII`.
15	 *
16	 * ASCII code points are passed through untouched, other whitespace collapses to
17	 * a plain space, other decimal digits become their ASCII counterpart, and
18	 * anything else becomes '?' so the scanner below rejects it.
19	 */
20	function transformDecimalAndSpaceToAscii(text) {
21	  let out = '';
22	  for (const character of text) {
23	    const codePoint = character.codePointAt(0);
24	    if (codePoint < 127) {
25	      out += character;
26	    } else if (isNonAsciiSpace(codePoint)) {
27	      out += ' ';
28	    } else {
29	      const digit = decimalValue(codePoint);
30	      out += digit < 0 ? '?' : String(digit);
31	    }
32	  }
33	  return out;
34	}
35	
36	function invalidLiteral(text) {
37	  return new PyValueError(
38	    `invalid literal for int() with base 10: ${JSON.stringify(text)}`,
39	  );
40	}
41	
42	/**
43	 * `PyLong_FromString` for base 10: optional surrounding whitespace, an optional
44	 * sign that must be followed immediately by a digit, and digit groups that may
45	 * be separated by single underscores.
46	 *
47	 * @param {string} text
48	 * @returns {bigint}
49	 */
50	export function pyInt(text) {
51	  if (typeof text !== 'string') {
52	    throw new PyValueError('pyInt() expects a string');
53	  }
54	
55	  const scanned = transformDecimalAndSpaceToAscii(text);
56	  const length = scanned.length;
57	  let index = 0;
58	
59	  while (index < length && isAsciiSpace(scanned.charCodeAt(index))) index += 1;
60	
61	  let negative = false;
62	  if (index < length && (scanned[index] === '+' || scanned[index] === '-')) {
63	    negative = scanned[index] === '-';
64	    index += 1;
65	  }
66	
67	  let digits = '';
68	  let previousWasDigit = false;
69	  while (index < length) {
70	    const character = scanned[index];
71	    if (character >= '0' && character <= '9') {
72	      digits += character;
73	      previousWasDigit = true;
74	      index += 1;
75	    } else if (character === '_' && previousWasDigit) {
76	      // A single underscore is allowed, but only wedged between two digits;
77	      // `previousWasDigit` going false here rejects '1__0' and '5_'.
78	      previousWasDigit = false;
79	      index += 1;
80	    } else {
81	      break;
82	    }
83	  }
84	
85	  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);
86	
87	  while (index < length && isAsciiSpace(scanned.charCodeAt(index))) index += 1;
88	  if (index !== length) throw invalidLiteral(text);
89	
90	  const magnitude = BigInt(digits);
91	  return negative ? -magnitude : magnitude;
92	}
