95	 * The callable handed to `parser.add_argument(..., type=int)`. `typeName` stands
96	 * in for Python's `int.__name__`, which argparse interpolates into its
97	 * "invalid int value" diagnostic.
98	 */
99	export const int = (text) => pyInt(text);
