// Audit of /output/lib/networkx/utils/hashing.mjs -- nodeKey equivalence.
import { nodeKey } from '/output/lib/networkx/utils/hashing.mjs';

let fails = 0;
const ok = (cond, msg, extra = '') => {
  if (!cond) { fails++; console.log('FAIL:', msg, extra); }
};

// --- integer Number / BigInt / boolean unification -------------------------
ok(nodeKey(1) === nodeKey(1n), 'Number 1 vs BigInt 1n', `${nodeKey(1)} ${nodeKey(1n)}`);
ok(nodeKey(1) === nodeKey(true), 'Number 1 vs true');
ok(nodeKey(0) === nodeKey(false), 'Number 0 vs false');
ok(nodeKey(1.0) === nodeKey(1n), '1.0 vs 1n');
ok(nodeKey(-0) === nodeKey(0n), '-0 vs 0n', `${nodeKey(-0)} ${nodeKey(0n)}`);
ok(nodeKey(2 ** 53) === nodeKey(9007199254740992n), '2**53');
ok(nodeKey(1e21) === nodeKey(10n ** 21n), '1e21 vs 10**21', `${nodeKey(1e21)} ${nodeKey(10n ** 21n)}`);

// --- huge BigInts never collide -------------------------------------------
const bigs = [
  10n ** 30n, 10n ** 30n + 1n,
  99999999999999999999998n, 99999999999999999999999n,
  -(10n ** 40n), -(10n ** 40n) - 1n,
  2n ** 1024n, 2n ** 1024n + 1n,
];
const seenBig = new Map();
for (const b of bigs) {
  const k = nodeKey(b);
  ok(!seenBig.has(k), `huge BigInt collision ${b} vs ${seenBig.get(k)}`);
  seenBig.set(k, b);
}

// --- numeric vs string vs tuple vs None vs object --------------------------
const probes = [
  ['int 1', 1n], ['float 1.5', 1.5], ['str "1"', '1'], ['str "i1"', 'i1'],
  ['str ""', ''], ['str "None"', 'None'], ['none', null], ['undef', undefined],
  ['tuple []', []], ['tuple [1]', [1n]], ['tuple [1,2]', [1n, 2n]],
  ['nan', NaN], ['inf', Infinity], ['-inf', -Infinity],
  ['str ":nan"', ':nan'], ['float :nan-lookalike', 0.5],
  ['str "t1[2:i1]"', 't1[2:i1]'],
];
const seen = new Map();
for (const [label, v] of probes) {
  const k = nodeKey(v);
  if (label === 'none' || label === 'undef') continue; // both intentionally None
  ok(!seen.has(k), `key collision: ${label} vs ${seen.get(k)} => ${JSON.stringify(k)}`);
  seen.set(k, label);
}
ok(nodeKey(null) === nodeKey(undefined), 'null and undefined both None');

// --- tuple encoding unambiguity -------------------------------------------
// Brute force: generate many nested tuples from a small alphabet and check
// that distinct structures never share a key.
function* atoms() {
  yield 0n; yield 1n; yield 12n; yield '';
  yield '1'; yield '12'; yield ':'; yield ']'; yield '['; yield '1:1';
  yield 'i1'; yield 't1[2:i1]'; yield null;
