const atomList = [...atoms()];
const structs = [];
for (const a of atomList) structs.push(a);
for (const a of atomList) for (const b of atomList) structs.push([a, b]);
for (const a of atomList) structs.push([a]);
for (const a of atomList) for (const b of atomList) structs.push([[a], b], [a, [b]], [[a, b]]);

