// --- remainingInDegree bookkeeping: never negative, never NaN, never missed
// Instrument by re-running the algorithm and checking invariants directly.
function kahnInvariants(G) {
  // recompute what the module computes, watching every intermediate value
  const remaining = new Map();
  let zero = [];
  for (const [node, d] of G.in_degree()) {
    if (d > 0) remaining.set(G.key(node), d); else zero.push(node);
  }
  const problems = [];
  while (zero.length) {
    const gen = zero; zero = [];
    for (const node of gen) {
      for (const child of G.neighbors(node)) {
        const ck = G.key(child);
        if (!remaining.has(ck)) problems.push(`missing entry for ${String(child)}`);
        const r = remaining.get(ck) - 1;
        if (Number.isNaN(r)) problems.push(`NaN for ${String(child)}`);
        if (r < 0) problems.push(`negative for ${String(child)}`);
        remaining.set(ck, r);
        if (r === 0) { zero.push(child); remaining.delete(ck); }
      }
    }
  }
  return problems;
}

