// randomized differential: brute-force cycle detection (DFS) vs Kahn
function dfsHasCycle(G) {
  const WHITE = 0, GREY = 1, BLACK = 2;
  const color = new Map();
  for (const n of G.nodes()) color.set(G.key(n), WHITE);
  const visit = (n) => {
    const k = G.key(n);
    if (color.get(k) === GREY) return true;
    if (color.get(k) === BLACK) return false;
    color.set(k, GREY);
    for (const c of G.neighbors(n)) if (visit(c)) return true;
    color.set(k, BLACK);
    return false;
  };
  for (const n of G.nodes()) if (visit(n)) return true;
  return false;
}

